      if (i >= 0) { L.sections[i] = s; return; }
      if (s.after) { var j = -1; L.sections.forEach(function (x, k) { if (x.id === s.after) j = k; }); if (j >= 0) { L.sections.splice(j + 1, 0, s); return; } }
      if (s.first) { L.sections.unshift(s); return; }
